                "LONGBLOB",
                "ENUM",
                "SET",
                "DATE",
                "TIME",
                "DATETIME",
                "YEAR",
                "TIMESTAMP",
                "JSON"
              ]
            },
            "minProperties": 1
          }
        }
      },
      "required": [
        "db_name",
        "db_tables"
      ]
    },
    "dbs": {
      "type": "object",
      "properties": {
        "dbs_addr": {
          "anyOf": [
            {
              "type": "string",
