              "atom1.0",
              "blogger",
              "buddycloud",
              "diaspora",
              "dreamwidth",
              "drupal",
              "facebook",
              "friendica",
              "gnusocial",
              "google",
              "insanejournal",
              "libertree",
              "linkedin",
              "livejournal",
              "mediagoblin",
              "myspace",
              "pinterest",
              "pnut",
              "posterous",
              "pumpio",
              "redmatrix",
              "rss2.0",
              "smtp",
              "tent",
              "tumblr",
              "twitter",
              "wordpress",
              "xmpp"
            ]
          }
        }
      }
    },
    "openRegistrations": {
      "description": "Whether this server allows open self-registration.",
      "type": "boolean"
    },
    "usage": {
      "description": "Usage statistics for this server.",
      "type": "object",
      "additionalProperties": false,
      "required": [
